            @NotBlank(message = "operator 不能为空") String operator,
            @NotBlank(message = "bagTag 不能为空") String bagTag) {
    }

    /** 队列成员明细：含已出队/已撤队历史，序号保留不重排。 */
    public record QueueMemberItem(int seq, String bagTag, String status) {
